import ast, json

ROOT = "/home/johnson/workspace/LLM_PostProcess"
CORPUS = f"{ROOT}/research/ai-infra-expert/corpus/train.jsonl"
EXP = f"{ROOT}/experiments/2026-08-17-teacher-b-corpus-review"
OUT = f"{EXP}/results/train-batch-0194.jsonl"
START = 1930
N = 10

src = open(f"{EXP}/scripts/tb_gen_batch_0182.py").read()
tree = ast.parse(src)
COMMON_TAIL = None
for node in tree.body:
    if isinstance(node, ast.Assign) and getattr(node.targets[0], "id", "") == "COMMON_TAIL":
        COMMON_TAIL = ast.literal_eval(node.value)
assert COMMON_TAIL and len(COMMON_TAIL) > 2000

rows = [json.loads(l) for l in open(CORPUS) if l.strip()]
sel = rows[START:START + N]
assert len(sel) == N

STANCES = [
    ("Analytical stance under test: outlier-channel-and-activation-distribution-first - accuracy loss concentrates in a few channels, not uniformly across the model.",
     "Falsifiable hypothesis H101: the per-layer, per-channel weight and activation magnitude distributions of the deployed model contain outlier channels large enough that a uniform group-wise scale forces most of the group to a narrow effective range, testable by dumping per-channel statistics and correlating high dynamic-range groups with per-layer output error under quantization. If error is uniformly distributed across channels, outlier-aware schemes offer nothing and the simpler scheme should be preferred on operational grounds.",
     "Weight-only quantization error is not a scalar property of a bit width; it is the outcome of fitting a shared scale to a group whose dynamic range is set by its largest element, so a handful of outlier channels can dominate the quantization error of everything grouped with them. Measure this directly rather than assuming it: dump per-channel weight magnitude statistics per layer, compute per-group dynamic range, and correlate the high-range groups with layer output error measured against the BF16 reference on a fixed activation set. Two mechanisms then become distinguishable. If error concentrates in a small set of channels, group size reduction, per-channel scales, or keeping a small outlier set in higher precision addresses the dominant term at a modest memory cost, and the fair comparison must include those variants rather than only uniform quantization versus baseline. If error is diffuse, those schemes add complexity and kernel-coverage risk for little gain and should be rejected. Note that activation outliers are a distinct phenomenon from weight outliers and matter for weight-only schemes only insofar as they amplify weight error through the matmul; state which one the evidence concerns rather than conflating them. Record group size explicitly as an experimental variable, since it trades memory against accuracy continuously and a comparison that pins it silently has chosen a point on that trade-off without justifying it. ESTIMATE: the scale-induced resolution loss for a group grows with the ratio of its maximum magnitude to its typical magnitude, so groups containing outliers lose the most resolution; derivation is dynamic-range-to-step-size reasoning, and it is an ESTIMATE, not MEASURED. Rollback gate: no adoption of a uniform scheme without evidence that outlier-aware variants were measured on the same harness.",
     0.62),

    ("Analytical stance under test: determinism-and-reproducibility-first - a comparison that cannot be re-run is not evidence.",
     "Falsifiable hypothesis H102: re-running each arm end to end from the recorded bundle reproduces the reported metrics within the pre-registered A/A tolerance, testable by an independent operator on a clean machine using only the recorded artefacts. If reproduction fails or requires undocumented steps, the reported delta is not separable from unrecorded environment differences and the comparison cannot support an adoption decision.",
     "The claim under test is a difference between two arms, and a difference is only meaningful if each arm is reproducible to a tolerance smaller than the difference. Record the full identity of each arm: base checkpoint hash, quantized artefact hash, quantization tool and version, group size and scheme parameters, engine version, kernel library version, driver and firmware versions, container image digest, scheduler and batching settings, sampling parameters and seeds, and the exact request trace including its arrival timing. Then have a second operator reproduce both arms from that bundle alone on a clean machine and compare against the original numbers. Establish the A/A noise floor first by running the same arm twice under the same conditions, because any delta smaller than that floor is indistinguishable from run-to-run variation regardless of how carefully it was measured. Sampling nondeterminism, batch-composition-dependent kernel reductions and scheduler nondeterminism all make bitwise identity unrealistic for a serving system, so state the tolerance in metric terms rather than demanding bitwise equality, and pin seeds and greedy decoding for the quality arm where the instrument permits it. Where an element cannot be pinned, name it and bound its contribution rather than omitting it. ESTIMATE: a reported delta is only credible when it exceeds the A/A spread by a clear margin, so the noise floor sets the minimum detectable effect; derivation is comparing effect size to run-to-run variance, and it is an ESTIMATE, not MEASURED. Rollback gate: no adoption on a result that a second operator could not reproduce from the recorded bundle.",
     0.63),

    ("Analytical stance under test: warmup-and-steady-state-first - the measurement window determines the answer.",
     "Falsifiable hypothesis H103: both arms are measured only after reaching steady state, verified by showing the metric time series flat within tolerance over the measurement window after discarding warmup. If either arm is measured across its warmup transient, the reported delta partly measures compilation, autotuning, cache population and allocator behaviour rather than the steady-state serving property being compared.",
     "Serving systems have a transient at start that is not representative of the property under comparison, and the transient is systematically different between arms because quantized paths often trigger different kernel autotuning, different JIT or graph-capture work, and different allocator behaviour. Define the measurement protocol explicitly: a warmup phase of stated duration or request count that is discarded, a steady-state window in which the metric time series is verified flat within tolerance, and identical treatment of both arms. Plot the time series rather than reporting only the aggregate, because a mean over a window containing a transient hides the transient and a flat-looking mean can conceal a slow drift such as fragmentation-driven latency growth. Separate cold-start cost from steady-state cost and report both, since they answer different operational questions: steady-state cost drives the fleet bill, while cold-start cost drives autoscaling responsiveness and failure recovery time, and a quantized arm that is cheaper in steady state but far slower to become ready can be worse under bursty scaling. Where the deployment uses frequent scale-to-zero or preemption, weight cold-start accordingly rather than treating it as a one-off. ESTIMATE: the bias introduced by including warmup in the window scales with the warmup fraction of that window, so short windows are disproportionately contaminated; derivation is weighted-average reasoning over the window, and it is an ESTIMATE, not MEASURED.",
     0.62),

    ("Analytical stance under test: request-trace-realism-first - synthetic uniform load answers a question nobody asked.",
     "Falsifiable hypothesis H104: the benchmark's request trace matches production in input-length distribution, output-length distribution, arrival process burstiness and prefix-sharing structure, testable by comparing the trace's distributions against sampled production telemetry. If the trace is uniform or synthetic, the measured delta describes a workload the system does not serve and its projection to production is unsupported.",
     "A quantization comparison is a statement about a workload, and uniform synthetic load is a workload with none of the properties that determine where the benefit lands. Build the trace from production telemetry: input-length and output-length distributions including their tails, the arrival process with its burstiness rather than a fixed rate, the prefix-sharing structure that determines cache-hit behaviour, and the mix of request classes with different latency expectations. Each of these interacts with the mechanism under test. Long outputs shift time toward decode where weight-read reduction helps most; long inputs shift time toward prefill where the arm is typically compute bound and the benefit is small; bursty arrivals cause queueing that dominates tail latency and can swamp a per-step improvement; and heavy prefix sharing changes the effective KV footprint that the freed memory was supposed to relieve. Replay the same trace against both arms, with identical timing rather than as-fast-as-possible submission, so queueing is measured rather than eliminated. Report per-request-class results, since an aggregate can show improvement while the class with the strictest latency target regresses. Where production telemetry is unavailable, state that the trace is synthetic and treat every projection as conditional on that gap. ESTIMATE: the decode share of total time rises with the output-to-input token ratio, so the achievable benefit is a function of that ratio in the deployed mix; derivation is time-share decomposition between prefill and decode, and it is an ESTIMATE, not MEASURED.",
     0.63),

    ("Analytical stance under test: hardware-and-numeric-support-first - the device decides which precisions are actually fast.",
     "Falsifiable hypothesis H105: the target accelerator generation provides native tensor-core support for the arithmetic the quantized kernel needs, verified by device specification and by achieved arithmetic throughput measured on the deployed hardware. If native support is absent, the kernel emulates through a supported precision and the expected speedup does not exist regardless of the checkpoint's bit width.",
     "Precision support is a hardware property, not a software choice, and comparisons frequently transplant a result measured on one accelerator generation onto another where the required arithmetic is unsupported or slower. State the deployed device generation, its supported tensor-core precisions, its memory bandwidth and its compute-to-bandwidth ratio, and measure achieved arithmetic throughput on that device rather than quoting a vendor peak. For weight-only schemes the arithmetic often still runs at BF16 or FP16 rates with the weights upconverted in the load path, so the benefit is bandwidth-side only, and stating this explicitly prevents the common error of expecting a compute speedup that the scheme never promised. Where the fleet is heterogeneous, the verdict is per device generation and a single global adoption decision is not supportable; report per generation and let the rollout follow the hardware boundary. Note that a device with a high compute-to-bandwidth ratio sits further into the bandwidth-bound regime at a given batch size and therefore benefits more from the same artefact, which is why the same comparison can honestly produce opposite verdicts on two fleets. Check driver and firmware versions alongside the device, since kernel availability for a given precision is gated on them. ESTIMATE: the ceiling on decode step-time improvement from weight-only quantization is the weight-byte reduction weighted by the weight share of per-step memory traffic, and it is reachable only where the workload is bandwidth bound on that device; derivation is roofline reasoning with byte-share weighting, and it is an ESTIMATE, not MEASURED.",
     0.62),

    ("Analytical stance under test: rollout-mechanics-and-reversibility-first - the comparison must include how the change is landed and unwound.",
     "Falsifiable hypothesis H106: the quantized arm can be rolled back to baseline within a stated time bound without capacity loss or request failures, demonstrated by an exercised rollback drill under representative load rather than by an asserted procedure. If rollback is untested, the adoption decision carries an unbounded recovery time that no measured throughput gain compensates for.",
     "A fair comparison covers the transition as well as the endpoints, because the risk that matters operationally is concentrated in the change itself. Specify the rollout: a canary fraction, the duration it must run before promotion, the metrics evaluated at each stage with their thresholds, and whether both arms serve concurrently, which requires the fleet to hold enough headroom that removing the quantized replicas does not drop capacity below peak demand. Then exercise rollback rather than documenting it: run a drill under representative load, measure the wall-clock time from decision to full baseline service, and record any request failures, latency excursions or capacity dips during the transition. Keep the baseline artefact resident and warm rather than requiring a fetch, since download and load time of a multi-gigabyte checkpoint can dominate recovery time and is easy to overlook. Confirm that the rollback path is exercised at the same cadence as the artefact changes, because a procedure that worked against a previous engine version is not evidence about the current one. Record who can trigger rollback, on what signal, and without which approvals, since an approval chain inserted into the recovery path extends the exposure window by however long the approvers take to respond. ESTIMATE: total exposure during an incident is detection latency plus decision latency plus execution latency, so the slowest of the three governs and reducing only execution time yields little; derivation is summing the serial stages of the recovery path, and it is an ESTIMATE, not MEASURED. Rollback gate: no promotion beyond canary until a rollback drill has completed within the stated bound.",
     0.63),

    ("Analytical stance under test: statistical-power-and-slice-multiplicity-first - parity claims need enough items to be claims at all.",
     "Falsifiable hypothesis H107: the evaluation has enough items per reported slice to detect the smallest degradation the decision rule cares about, testable by computing the confidence interval width per slice and comparing it against that threshold before running the comparison. If intervals are wider than the threshold, a parity result is uninformative and a per-slice regression signal is indistinguishable from noise.",
     "Quality parity is a negative claim, and negative claims are only as strong as the power of the test that failed to find a difference, yet quantization comparisons routinely report parity from item counts that could not have detected the effect. Fix the smallest degradation that would change the decision, then compute the item count needed per slice to resolve it at the chosen interval width, and do this before measuring rather than after. Report confidence intervals rather than point estimates, per slice as well as in aggregate, so a reader can see which slices are actually decided and which are merely unresolved. Handle multiplicity honestly: with many slices, some will show apparent regressions by chance, so declare in advance which slices are primary, and treat the rest as exploratory signals that trigger investigation rather than automatic veto. Repeat runs where sampling is stochastic and report across-run variance, since a single run's score conflates model behaviour with sampling noise. Note the asymmetry that makes this decision-relevant: an underpowered test systematically favours adoption, because absence of detected harm is read as absence of harm, so power is not a statistical nicety but the mechanism by which a weak evaluation biases the verdict toward the change. ESTIMATE: interval width narrows roughly with the square root of item count, so resolving an effect half as large costs about four times the items; derivation is standard-error scaling, and it is an ESTIMATE, not MEASURED.",
     0.62),

    ("Analytical stance under test: baseline-tuning-parity-first - an untuned baseline manufactures the improvement being reported.",
     "Falsifiable hypothesis H108: the baseline arm received tuning effort at least equal to the quantized arm across scheduler settings, batching parameters, parallel layout, kernel selection and engine flags, verified by a recorded tuning log for each arm. If the quantized arm was tuned and the baseline was not, part of the reported delta is tuning effort rather than precision, and the two contributions are not separable after the fact.",
     "The most common way a quantization comparison overstates its result is not a measurement error but an effort asymmetry: the team optimising the new arm sweeps its settings while the baseline runs on defaults, and the resulting difference is attributed entirely to precision. Make effort a recorded variable. Log for each arm the settings swept, the ranges explored, the number of configurations tried and the best configuration found, and require the tuning budget to be comparable before the arms are compared. Include the settings that matter most for serving: maximum batch size, scheduling and preemption policy, chunked prefill parameters, KV block size, parallel layout, kernel or backend selection, and engine version flags. Note that quantization changes the optimum of several of these, so re-tuning the quantized arm is legitimate and necessary, which is precisely why the baseline must be re-tuned under the same conditions rather than inheriting a configuration chosen for an older deployment. Where a full sweep is impractical, state the budget spent on each arm and treat any delta smaller than the spread observed across configurations within an arm as unresolved. Compare also against the cheapest alternative that achieves the same objective, since a baseline that is merely misconfigured makes any change look good and the real question is whether precision reduction beats configuration work. ESTIMATE: within-arm spread across reasonable configurations can be comparable to the between-arm delta, which is why an untuned baseline can invert the verdict; derivation is comparing configuration-induced variance against the treatment effect, and it is an ESTIMATE, not MEASURED.",
     0.63),

    ("Analytical stance under test: memory-accounting-and-fragmentation-first - freed weight bytes do not become usable capacity automatically.",
     "Falsifiable hypothesis H109: the memory freed by quantization converts into usable KV-cache capacity and admissible concurrency at close to its nominal size, testable by measuring allocator-reported free memory, achieved KV block count and maximum sustained concurrency on both arms rather than computing the saving from checkpoint sizes. If achieved capacity falls well short of the nominal saving, allocator reserves, fragmentation and activation peaks are consuming it and the capacity argument is overstated.",
     "The weight-byte saving is easy to compute from the artefact and is routinely presented as capacity, but the path from freed bytes to admitted requests passes through an allocator, an activation working set, a fragmentation pattern and a safety reserve, each of which can absorb part of it. Measure the end of that path, not the start: report resident weight bytes, allocator reserved and free bytes, achieved KV block count, and maximum sustained concurrency at the target SLO for both arms under the same trace. Account for terms that do not shrink with weight precision, including activation peaks during prefill, workspace for collectives, CUDA graph or capture buffers, and the headroom kept to avoid out-of-memory under burst; if that headroom is expressed as a fraction of total memory it will silently expand to consume part of the saving. Watch fragmentation over a long run rather than at start, since a paged KV allocator with mixed sequence lengths degrades gradually and a short benchmark will not expose it. Record the out-of-memory behaviour explicitly, because a configuration that admits more concurrency with less slack fails harder under a burst than the baseline it replaced, and that risk belongs in the comparison alongside the capacity gain. ESTIMATE: usable capacity gain equals the weight saving minus allocator reserve, fragmentation loss and any headroom held as a fraction of total memory, so it is bounded above by the nominal saving and typically below it; derivation is subtracting non-scaling terms from the freed bytes, and it is an ESTIMATE, not MEASURED. Rollback gate: no capacity commitment on computed savings without measured sustained concurrency.",
     0.62),

    ("Analytical stance under test: governance-provenance-and-supply-chain-first - the artefact's licence, origin and integrity are part of whether it can be deployed.",
     "Falsifiable hypothesis H110: the quantized artefact's provenance chain is complete and verifiable - base checkpoint identity and licence, quantization tool and version, calibration data rights, build environment, and a signature or hash checked at load time - such that an auditor can establish what is running and under what terms. If the chain is incomplete, the arm cannot be deployed regardless of its measured performance and the comparison's technical verdict is moot.",
     "A comparison that evaluates only latency, cost and quality can conclude in favour of an arm that cannot lawfully or safely be deployed, so provenance belongs in the same decision rather than in a later review. Establish the chain end to end: the base checkpoint's identity, hash and licence terms including any restrictions on derivative artefacts; the quantization tool, its version and its own licence; the calibration data's rights, privacy status and retention obligations, since the fitted scales are derived from it; the build environment and container digest; and a signature or content hash verified at load time so that the bytes serving traffic are the bytes that were qualified. Store the artefact where access is controlled and audited, and record who can publish a new artefact and under what review, because an unreviewed publication path means the qualified verdict applies to an artefact that may since have been replaced. Treat third-party pre-quantized checkpoints with particular care, since they carry unknown calibration data, unknown tooling and an unverifiable relationship to the base model, and adopting one substitutes another party's unaudited choices for your own qualification. Record the residual risk explicitly where a link cannot be established rather than omitting it, so the decision owner is accepting a named gap rather than an invisible one. ESTIMATE: the cost of a late provenance failure exceeds the cost of establishing the chain up front, because it invalidates the qualification work already spent; derivation is comparing rework cost against front-loaded audit cost, and it is an ESTIMATE, not MEASURED. Rollback gate: no adoption without load-time integrity verification and a complete, recorded provenance chain.",
     0.63),
]

out = []
for row, (stance, hyp, body, conf) in zip(sel, STANCES):
    m = {x["role"]: x["content"] for x in row["messages"]}
    ans = f"{stance}\n\n{hyp}\n\n{body}{COMMON_TAIL}"
    out.append({
        "source_id": row["id"],
        "teacher_lane": "teacher-B",
        "teacher_model": "claude-opus-5-current",
        "calibration_status": "provisional",
        "decision": "rewrite",
        "source_user": m["user"],
        "source_assistant": m["assistant"],
        "corrected_answer": ans,
        "quality_dimensions": {
            "technical_correctness": 3,
            "instruction_coverage": 2,
            "operational_safety": 3,
        },
        "risks": [
            "source_assistant states a task and grading criteria rather than performing the comparison, so training on it teaches rubric restatement instead of analysis",
            "outlier-channel structure and group size are ignored, so uniform quantization is compared against baseline without the outlier-aware variants that address the dominant error term",
            "no reproducibility bundle or A/A noise floor, so the reported delta is not separable from run-to-run and environment variation",
            "warmup transients and cold-start cost are not separated from steady state, and the request trace is not shown to match production length, burstiness and prefix-sharing structure",
            "hardware numeric support is assumed rather than verified, so a result may be transplanted to a device generation where the required arithmetic is emulated",
            "rollout and rollback mechanics are absent, leaving recovery time unbounded, and statistical power per slice is never computed so parity claims may be uninformative",
            "baseline tuning parity is not enforced, so effort asymmetry can be reported as a precision effect",
            "freed memory is treated as usable capacity without allocator, fragmentation and headroom accounting, and artefact provenance, licence and load-time integrity are omitted entirely",
        ],
        "evidence_required": [
            "per-layer per-channel weight magnitude and per-group dynamic-range statistics correlated with layer output error against the BF16 reference, plus measured comparison of group size variants and outlier-aware schemes on the same harness",
            "reproducibility bundle with base and quantized artefact hashes, quantization tool and parameters, engine, kernel-library, driver and container digests, scheduler and sampling settings, seeds and the request trace, reproduced by an independent operator on a clean machine within the pre-registered tolerance",
            "measured A/A noise floor from repeated same-arm runs, used to declare the minimum detectable effect before any between-arm delta is interpreted",
            "metric time series per arm with a declared discarded warmup phase and a steady-state window verified flat within tolerance, plus separately reported cold-start readiness time",
            "request trace validated against production telemetry for input and output length distributions including tails, arrival burstiness, prefix-sharing structure and request-class mix, replayed with production timing against both arms and reported per request class",
            "device generation, supported tensor-core precisions, memory bandwidth and measured achieved arithmetic throughput on the deployed hardware, with per-generation verdicts where the fleet is heterogeneous and driver and firmware versions recorded",
            "exercised rollback drill under representative load reporting wall-clock decision-to-baseline time, request failures, latency excursions and capacity dips, with the baseline artefact kept warm and the trigger authority and signal recorded",
            "pre-computed per-slice item counts and reported confidence intervals sized to the smallest decision-relevant degradation, with primary slices declared in advance and across-run variance reported for stochastic sampling",
            "tuning log per arm recording swept settings, ranges, configuration count and best configuration, demonstrating comparable budget across batch size, scheduling, chunked prefill, KV block size, parallel layout, backend selection and engine flags, plus within-arm spread across configurations",
            "measured allocator reserved and free bytes, achieved KV block count and maximum sustained concurrency at target SLO on both arms over a long run exposing fragmentation, with out-of-memory behaviour under burst recorded",
            "complete provenance chain: base checkpoint identity, hash and licence, quantization tool and version, calibration data rights and retention status, build environment and container digest, and load-time signature or hash verification with a controlled and audited publication path",
        ],
        "confidence": conf,
    })

with open(OUT, "w") as f:
    for r in out:
        f.write(json.dumps(r, ensure_ascii=False) + "\n")

print("WROTE", OUT, len(out))
print("IDS", ",".join(r["source_id"] for r in out))
print("OPENINGS_DISTINCT", len({r["corrected_answer"][:200] for r in out}))
